import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(data[2 + i]) for i in range(n)]
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + a[i]
    best = {}
    res = None
    for j in range(n):
        x = a[j]
        for v in (x - k, x + k):
            if v in best:
                mp, i = best[v]
                cand = (-(P[j + 1] - mp), i, j)
                if res is None or cand < res:
                    res = cand
        if x not in best or P[j] < best[x][0]:
            best[x] = (P[j], j)
    print(-1 if res is None else f"{res[1]} {res[2]}")

main()

